@page "/apply"
@rendermode InteractiveServer
@using sv_84fbfa7d24174c1e9f6c85632cd9cae2.Models
@using sv_84fbfa7d24174c1e9f6c85632cd9cae2.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h3 class="mb-4">Job Application</h3>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo"
                                  ApplicationService="ApplicationService"
                                  OnNext="() => CompleteAndAdvance(1)" />
                break;

            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="() => CompleteAndAdvance(2)"
                                 OnBack="() => GoToStep(1)" />
                break;

            case 3:
                <ReferencesStep References="references"
                                OnNext="() => CompleteAndAdvance(3)"
                                OnBack="() => GoToStep(2)" />
                break;

            case 4:
                <CoverLetterStep @bind-CoverLetter="coverLetter"
                                 OnNext="() => CompleteAndAdvance(4)"
                                 OnBack="() => GoToStep(3)" />
                break;

            case 5:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="coverLetter"
                            ApplicationService="ApplicationService"
                            OnEditStep="GoToStep"
                            OnBack="() => GoToStep(4)" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = [];

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void CompleteAndAdvance(int step)
    {
        completedSteps.Add(step);
        currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }
}

using sv_84fbfa7d24174c1e9f6c85632cd9cae2.Models;

namespace sv_84fbfa7d24174c1e9f6c85632cd9cae2.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // simulate network call
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500); // simulate network call
        return !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
    }
}

